From 980e5e03247c65991fada3c806379c88a2013fef Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:54:40 +0100
Subject: [PATCH] popupplasmawindow: center panel popups when they still cover
 their button

Applet popups were always centered on the item that opened them, so a
launcher placed near the middle of a panel opened off center. Now the
popup snaps to the panel's center when it would still cover that item.

BUG: 499472
---
 src/plasmaquick/popupplasmawindow.cpp | 14 ++++++++++++++
 1 file changed, 14 insertions(+)

diff --git a/src/plasmaquick/popupplasmawindow.cpp b/src/plasmaquick/popupplasmawindow.cpp
index 3230442c9..7731987e0 100644
--- a/src/plasmaquick/popupplasmawindow.cpp
+++ b/src/plasmaquick/popupplasmawindow.cpp
@@ -144,6 +144,20 @@ void PopupPlasmaWindowPrivate::updatePosition()
     TransientPlacementHint placementHint;
     QRectF parentAnchorRect = QRectF(m_visualParent->mapToScene(QPointF(0, 0)), m_visualParent->size());

+    // Center popups on their panel when they would still cover the item they come from
+    auto *containmentView = qobject_cast<ContainmentView *>(m_visualParent->window());
+    if (containmentView && containmentView->location() != Plasma::Types::Floating && containmentView->location() != Plasma::Types::Desktop
+        && containmentView->location() != Plasma::Types::FullScreen) {
+        const QPointF windowCenter = QRectF(QPointF(0, 0), containmentView->size()).center();
+        if (m_popupDirection == Qt::TopEdge || m_popupDirection == Qt::BottomEdge) {
+            if (qAbs(parentAnchorRect.center().x() - windowCenter.x()) + parentAnchorRect.width() / 2 <= q->width() / 2.0) {
+                parentAnchorRect.moveCenter(QPointF(windowCenter.x(), parentAnchorRect.center().y()));
+            }
+        } else if (qAbs(parentAnchorRect.center().y() - windowCenter.y()) + parentAnchorRect.height() / 2 <= q->height() / 2.0) {
+            parentAnchorRect.moveCenter(QPointF(parentAnchorRect.center().x(), windowCenter.y()));
+        }
+    }
+
     if (!m_floating) {
         QRect windowVisibleRect = m_visualParent->window()->mask().boundingRect();
         // pad parentAnchorRect to the window it's in, so that the popup appears outside the panel
